import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * A thread‑safe, XXE‑protected provider for Atom elements.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared Abdera engine – immutable and thread‑safe. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Flag controlling charset autodetection. */
    private boolean autodetectCharset;

    /* --------------------------------------------------------------------- */
    /* MessageBodyReader implementation                                       */
    /* --------------------------------------------------------------------- */

    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        /* Create a fresh ParserOptions instance for each request.  This guarantees
         * that the options are applied atomically before parsing and eliminates
         * any race condition that could arise from reusing a shared Parser
         * instance across threads. */
        ParserOptions options = new ParserOptions();
        options.setResolveEntities(false);          // Disable external entity resolution
        options.setAutodetectCharset(autodetectCharset);

        /* Obtain a new Parser configured with the safe options.  The Abdera
         * engine is immutable, so creating a new Parser per call is inexpensive
         * and fully thread‑safe. */
        Parser parser = ATOM_ENGINE.getParser(options);

        /* Parse the incoming stream.  The parser will honour the options above
         * and refuse to expand any external entities, mitigating XXE attacks. */
        Document<T> document = parser.parse(entityStream);

        return document.getRoot();
    }

    /* --------------------------------------------------------------------- */
    /* Other methods omitted for brevity                                      */
    /* --------------------------------------------------------------------- */
}
