 * @param i the raw value to be adjusted by {@code offset}
 * @throws IllegalArgumentException if {@code c} is {@code null}
 * @throws IllegalStateException    if {@code field} has not been initialized
 */
void setTo(Calendar c, int i) {
    if (c == null) {
        throw new IllegalArgumentException("Calendar instance cannot be null");
    }
    if (field == null) {
        throw new IllegalStateException("CalendarField has not been initialized");
    }

    // Compute the intended value and clamp it to the legal range for the field.
    int value = i - offset;
    int min = c.getActualMinimum(field);
    int max = c.getActualMaximum(field);

