private static String normalizePath(final String path) {
    // Preserve null values – callers may rely on this behaviour
    if (path == null) {
        return null;
    }

    // Trim surrounding whitespace to avoid accidental leading/trailing spaces
    String trimmed = path.trim();

    // An empty path should resolve to the root "/"
    if (trimmed.isEmpty()) {
        return "/";
    }

    // Count consecutive leading '/' characters
    int leadingSlashCount = 0;
    while (leadingSlashCount < trimmed.length()
            && trimmed.charAt(leadingSlashCount) == '/') {
        leadingSlashCount++;
    }

    // Remove all leading slashes and then prepend a single one
    String withoutLeading = trimmed.substring(leadingSlashCount);
    return "/" + withoutLeading;
}
