import java.io.OutputStream;
import java.nio.file.Files;
import org.apache.commons.compress.archivers.ArchiveEntry;

public class Expander {

    // other methods

    /**
     * Safely expands the contents of an archive into {@code targetDirectory}.
     *
     * <p>All entry names are validated to ensure that the resulting file path
     * cannot escape {@code targetDirectory}. The validation uses canonical
     * paths and rejects absolute paths, empty names, and names that resolve
     * outside the target directory. Directory creation is performed with
     * {@link Files#createDirectories} to guarantee that intermediate
     * directories are created atomically and safely.</p>
     *
     * @param supplier   supplies the next readable entry from the archive
     * @param writer     writes the data of an entry to an {@link OutputStream}
     * @param targetDirectory the root directory where the archive will be expanded
     * @throws IOException if an I/O error occurs or a path traversal attempt is detected
     */
    private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
        // Resolve the canonical path of the target directory once
        final java.nio.file.Path targetDirPath = targetDirectory.getCanonicalFile().toPath();

        ArchiveEntry nextEntry = supplier.getNextReadableEntry();
        while (nextEntry != null) {
            final String entryName = nextEntry.getName();

            // Basic sanity checks on the entry name
            if (entryName == null || entryName.isEmpty()) {
                throw new IOException("Archive entry has an empty name");
            }
            // Reject absolute paths – they would ignore the target directory
            if (new File(entryName).isAbsolute()) {
                throw new IOException("Archive entry name is absolute: " + entryName);
            }

            // Construct the target file and obtain its canonical path
            final File targetFile = new File(targetDirectory, entryName);
            final java.nio.file.Path canonicalTargetPath = targetFile.getCanonicalFile().toPath();

            // Ensure the canonical target path is still inside the target directory
            if (!canonicalTargetPath.startsWith(targetDirPath)) {
                throw new IOException("expanding " + entryName + " would create file outside of " + targetDirectory);
            }

            if (nextEntry.isDirectory()) {
                // Create the directory if it does not exist
                if (!targetFile.isDirectory() && !targetFile.mkdirs()) {
                    throw new IOException("failed to create directory " + targetFile);
                }
            } else {
                // Ensure the parent directory exists
                final File parent = targetFile.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("failed to create directory " + parent);
                }

                // Write the entry data to the target file
                try (OutputStream out = Files.newOutputStream(targetFile.toPath())) {
                    writer.writeEntryDataTo(nextEntry, out);
                }
            }

            // Proceed to the next entry
            nextEntry = supplier.getNextReadableEntry();
        }
    }

    // other methods

}
